insert into public.pokedex_entries (dex, number, species_id, is_default, ko_description, en_description) values
  ('alola', 15, 19, false, '평생 앞니가 계속 자란다. 너무 많이 자라면 먹이를 먹을 수 없어 굶어 죽는다.', 'Its incisors grow continuously throughout its life. If its incisors get too long, this Pokémon becomes unable to eat, and it starves to death.'),
  ('alola', 15, 10193, true, '평생 앞니가 계속 자란다. 너무 많이 자라면 먹이를 먹을 수 없어 굶어 죽는다.', 'Its incisors grow continuously throughout its life. If its incisors get too long, this Pokémon becomes unable to eat, and it starves to death.'),
  ('alola', 16, 20, false, '뒷발의 작의 물갈퀴로 바다를 헤엄쳐 섬을 건너 적을 피해 도망쳤다고 한다.', 'People say that it fled from its enemies by using its small webbed hind feet to swim from island to island in Alola.'),
  ('alola', 16, 10194, true, '뒷발의 작의 물갈퀴로 바다를 헤엄쳐 섬을 건너 적을 피해 도망쳤다고 한다.', 'People say that it fled from its enemies by using its small webbed hind feet to swim from island to island in Alola.'),
  ('alola', 33, 26, false, '몸에 전기가 쌓일수록 공격적으로 변한다. 사실은 전기가 스트레스라는 설도 있다.', 'As electricity builds up inside its body, it becomes more aggressive. One theory is that the electricity buildup is actually causing stress.'),
  ('alola', 33, 10202, true, '몸에 전기가 쌓일수록 공격적으로 변한다. 사실은 전기가 스트레스라는 설도 있다.', 'As electricity builds up inside its body, it becomes more aggressive. One theory is that the electricity buildup is actually causing stress.'),
  ('alola', 52, 52, false, '쓰레기장에 가면 빛이 나는 물건을 두고 니로우와 격렬하게 싸우는 광경을 볼 수 있다.', 'When visiting a junkyard, you may catch sight of it having an intense fight with Murkrow over shiny objects.'),
  ('alola', 52, 10209, true, '쓰레기장에 가면 빛이 나는 물건을 두고 니로우와 격렬하게 싸우는 광경을 볼 수 있다.', 'When visiting a junkyard, you may catch sight of it having an intense fight with Murkrow over shiny objects.'),
  ('alola', 53, 53, false, '알로라의 페르시온과는 이마의 보석 색깔이 다르지만, 성분은 크게 다르지 않다.', 'Although the jewel on its forehead appears to be a different color than those of Alolan Persian, it’s mostly made of the same material.'),
  ('alola', 53, 10210, true, '알로라의 페르시온과는 이마의 보석 색깔이 다르지만, 성분은 크게 다르지 않다.', 'Although the jewel on its forehead appears to be a different color than those of Alolan Persian, it’s mostly made of the same material.'),
  ('alola', 57, 88, false, '바다 밑의 진흙에서 태어났다. 청결한 장소에서는 체내의 세균이 증식되지 않아 죽어 버린다.', 'It was born from sludge on the ocean floor. In a sterile environment, the germs within its body can’t multiply, and it dies.'),
  ('alola', 57, 10214, true, '바다 밑의 진흙에서 태어났다. 청결한 장소에서는 체내의 세균이 증식되지 않아 죽어 버린다.', 'It was born from sludge on the ocean floor. In a sterile environment, the germs within its body can’t multiply, and it dies.'),
  ('alola', 58, 89, false, '먹이가 줄어들어 개체 수가 격감했다. 멸종을 방지하기 위해 인공 진흙 연못을 만들기 시작했다.', 'Their food sources have decreased, and their numbers have declined sharply. Sludge ponds are being built to prevent their extinction.'),
  ('alola', 58, 10215, true, '먹이가 줄어들어 개체 수가 격감했다. 멸종을 방지하기 위해 인공 진흙 연못을 만들기 시작했다.', 'Their food sources have decreased, and their numbers have declined sharply. Sludge ponds are being built to prevent their extinction.'),
  ('alola', 85, 50, false, '지하에 터널을 파서 이동한다. 빛을 싫어해서 해가 진 후에 지상으로 나온다.', 'It travels through tunnels that it digs underground. It hates sunlight, so it comes out only after the sun goes down.'),
  ('alola', 85, 10207, true, '지하에 터널을 파서 이동한다. 빛을 싫어해서 해가 진 후에 지상으로 나온다.', 'It travels through tunnels that it digs underground. It hates sunlight, so it comes out only after the sun goes down.'),
  ('alola', 86, 51, false, '언제나 사이좋은 세쌍둥이지만 극히 드물게 어느 머리가 먼저 먹이를 먹을까로 큰 싸움을 한다.', 'While the three of them normally get along splendidly, on rare occasions a huge fight will break out over which head gets to eat first.'),
  ('alola', 86, 10208, true, '언제나 사이좋은 세쌍둥이지만 극히 드물게 어느 머리가 먼저 먹이를 먹을까로 큰 싸움을 한다.', 'While the three of them normally get along splendidly, on rare occasions a huge fight will break out over which head gets to eat first.'),
  ('alola', 198, 105, false, '뼈를 던져 버랜지나를 떨어뜨린다. 부모의 원한을 갚기 위한 것으로 추측된다.', 'It throws bones at Mandibuzz to knock it down. It’s thought that Marowak is trying to avenge its parent.'),
  ('alola', 198, 10217, true, '뼈를 던져 버랜지나를 떨어뜨린다. 부모의 원한을 갚기 위한 것으로 추측된다.', 'It throws bones at Mandibuzz to knock it down. It’s thought that Marowak is trying to avenge its parent.'),
  ('alola', 298, 74, false, '오래 산 꼬마돌은 모가 없이 동그랗다. 성격도 매우 차분하고 온화하다.', 'Geodude that have lived a long life have had all their edges smoothed out until they’re totally round. They also have a calm, quiet disposition.'),
  ('alola', 298, 10211, true, '오래 산 꼬마돌은 모가 없이 동그랗다. 성격도 매우 차분하고 온화하다.', 'Geodude that have lived a long life have had all their edges smoothed out until they’re totally round. They also have a calm, quiet disposition.'),
  ('alola', 299, 75, false, '정상을 목표로 절벽을 오른다. 정상에 도착하면 곧바로 올라온 산길을 굴러 내려간다.', 'It climbs up cliffs as it heads toward the peak of a mountain. As soon as it reaches the summit, it rolls back down the way it came.'),
  ('alola', 299, 10212, true, '정상을 목표로 절벽을 오른다. 정상에 도착하면 곧바로 올라온 산길을 굴러 내려간다.', 'It climbs up cliffs as it heads toward the peak of a mountain. As soon as it reaches the summit, it rolls back down the way it came.'),
  ('alola', 300, 76, false, '나이가 들면 탈피를 하지 않는다. 긴 세월을 산 딱구리의 껍질은 이끼가 끼어 초록색이다.', 'When Golem grow old, they stop shedding their shells. Those that have lived a long, long time have shells green with moss.'),
  ('alola', 300, 10213, true, '나이가 들면 탈피를 하지 않는다. 긴 세월을 산 딱구리의 껍질은 이끼가 끼어 초록색이다.', 'When Golem grow old, they stop shedding their shells. Those that have lived a long, long time have shells green with moss.'),
  ('alola', 328, 27, false, '비가 적은 토지에 살고 있다. 위험한 상황이 되면 몸을 웅크려 부드러운 배를 지킨다.', 'It lives in areas of limited rainfall. When danger approaches, it curls up into a ball to protect its soft stomach.'),
  ('alola', 328, 10203, true, '비가 적은 토지에 살고 있다. 위험한 상황이 되면 몸을 웅크려 부드러운 배를 지킨다.', 'It lives in areas of limited rainfall. When danger approaches, it curls up into a ball to protect its soft stomach.'),
  ('alola', 329, 28, false, '발톱과 뿔이 잘 부러진다. 부러진 발톱과 뿔은 땅을 일구는 도구로 만들어진다.', 'Its claws and horns often break off. The broken claws and horns can be used to carve plows for tilling farm fields.'),
  ('alola', 329, 10204, true, '발톱과 뿔이 잘 부러진다. 부러진 발톱과 뿔은 땅을 일구는 도구로 만들어진다.', 'Its claws and horns often break off. The broken claws and horns can be used to carve plows for tilling farm fields.'),
  ('alola', 330, 37, false, '아름다운 꼬리 때문에 인기가 많다. 단 바지런히 빗질을 하지 않으면 순식간에 헝클어진다.', 'Its beautiful tails have made it very popular. However, if it’s not brushed diligently, it will be a mass of tangles before you know it.'),
  ('alola', 330, 10205, true, '아름다운 꼬리 때문에 인기가 많다. 단 바지런히 빗질을 하지 않으면 순식간에 헝클어진다.', 'Its beautiful tails have made it very popular. However, if it’s not brushed diligently, it will be a mass of tangles before you know it.'),
  ('alola', 331, 38, false, '끈질기고 집념이 강한 성질을 가졌다. 한 번 원한을 사면 자손을 포함해 1000년간 해를 입는다.', 'It is vindictive and relentless by nature. Those who cross it even once will be cursed for a thousand years, along with their descendants.'),
  ('alola', 331, 10206, true, '끈질기고 집념이 강한 성질을 가졌다. 한 번 원한을 사면 자손을 포함해 1000년간 해를 입는다.', 'It is vindictive and relentless by nature. Those who cross it even once will be cursed for a thousand years, along with their descendants.'),
  ('alola', 356, 103, false, '사이코 파워로 적을 대적한다. 3개의 머리가 각각 염동력을 발산해서 그 위력은 3배가 된다.', 'It engages its enemies using psychic powers. Each of its three heads fires off psychokinetic energy, tripling its power.'),
  ('alola', 356, 10216, true, '사이코 파워로 적을 대적한다. 3개의 머리가 각각 염동력을 발산해서 그 위력은 3배가 된다.', 'It engages its enemies using psychic powers. Each of its three heads fires off psychokinetic energy, tripling its power.'),
  ('galar', 31, 263, false, '뻣뻣한 털을 나무에 문질러서 영역을 표시한다. 가라르의 지그제구리보다 온순하다.', 'It marks its territory by rubbing its bristly fur on trees. This variety of Zigzagoon is friendlier and calmer than the kind native to Galar.'),
  ('galar', 31, 10333, true, '뻣뻣한 털을 나무에 문질러서 영역을 표시한다. 가라르의 지그제구리보다 온순하다.', 'It marks its territory by rubbing its bristly fur on trees. This variety of Zigzagoon is friendlier and calmer than the kind native to Galar.'),
  ('galar', 32, 264, false, '강하고 탄력 있는 털을 가졌다. 빠진 털로 만든 면도솔은 최고의 명품이다.', 'Its fur is strong and supple. Shaving brushes made with shed Linoone hairs are highly prized.'),
  ('galar', 32, 10334, true, '강하고 탄력 있는 털을 가졌다. 빠진 털로 만든 면도솔은 최고의 명품이다.', 'Its fur is strong and supple. Shaving brushes made with shed Linoone hairs are highly prized.'),
  ('galar', 182, 52, false, '빛나는 물건을 모으는 것을 좋아한다. 기분이 좋을 때는 트레이너에게도 컬렉션을 보여준다.', 'It loves to collect shiny things. If it’s in a good mood, it might even let its Trainer have a look at its hoard of treasures.'),
  ('galar', 182, 10320, true, '빛나는 물건을 모으는 것을 좋아한다. 기분이 좋을 때는 트레이너에게도 컬렉션을 보여준다.', 'It loves to collect shiny things. If it’s in a good mood, it might even let its Trainer have a look at its hoard of treasures.'),
  ('galar', 218, 83, false, '날개로 쥐고 있는 파 줄기를 칼처럼 휘둘러 상대를 베어버린다. 몹시 허기질 때는 먹기도 한다.', 'The stalk this Pokémon carries in its wings serves as a sword to cut down opponents. In a dire situation, the stalk can also serve as food.'),
  ('galar', 218, 10325, true, '날개로 쥐고 있는 파 줄기를 칼처럼 휘둘러 상대를 베어버린다. 몹시 허기질 때는 먹기도 한다.', 'The stalk this Pokémon carries in its wings serves as a sword to cut down opponents. In a dire situation, the stalk can also serve as food.'),
  ('galar', 226, 618, false, '갯벌이 보금자리다. 진흙 속에 사는 세균에 의해 전기를 만드는 기관이 발달했다.', 'Thanks to bacteria that lived in the mud flats with it, this Pokémon developed the organs it uses to generate electricity.'),
  ('galar', 226, 10339, true, '갯벌이 보금자리다. 진흙 속에 사는 세균에 의해 전기를 만드는 기관이 발달했다.', 'Thanks to bacteria that lived in the mud flats with it, this Pokémon developed the organs it uses to generate electricity.'),
  ('galar', 236, 222, false, '머리에 난 가지는 부러져도 다시 자란다. 예쁜 것은 순산을 기원하는 부적으로 쓰인다.', 'It will regrow any branches that break off its head. People keep particularly beautiful Corsola branches as charms to promote safe childbirth.'),
  ('galar', 236, 10332, true, '머리에 난 가지는 부러져도 다시 자란다. 예쁜 것은 순산을 기원하는 부적으로 쓰인다.', 'It will regrow any branches that break off its head. People keep particularly beautiful Corsola branches as charms to promote safe childbirth.'),
  ('galar', 251, 110, false, '2개의 몸에서 가스를 섞는다. 과거의 가라르에서는 흔하게 볼 수 있었다고 한다.', 'It mixes gases between its two bodies. It’s said that these Pokémon were seen all over the Galar region back in the day.'),
  ('galar', 251, 10326, true, '2개의 몸에서 가스를 섞는다. 과거의 가라르에서는 흔하게 볼 수 있었다고 한다.', 'It mixes gases between its two bodies. It’s said that these Pokémon were seen all over the Galar region back in the day.'),
  ('galar', 327, 562, false, '밤마다 유적을 떠돈다. 가지고 있는 마스크는 자신이 인간이던 시절의 얼굴이라고 한다.', 'It wanders through ruins by night, carrying a mask that’s said to have been the face it had when it was still human.'),
  ('galar', 327, 10338, true, '밤마다 유적을 떠돈다. 가지고 있는 마스크는 자신이 인간이던 시절의 얼굴이라고 한다.', 'It wanders through ruins by night, carrying a mask that’s said to have been the face it had when it was still human.'),
  ('galar', 333, 77, false, '갓 태어났을 때는 달리는 것이 서툴다. 동료와 달리기 경주를 하는 사이에 하반신이 튼튼하게 성장한다.', 'It can’t run properly when it’s newly born. As it races around with others of its kind, its legs grow stronger.'),
  ('galar', 333, 10321, true, '갓 태어났을 때는 달리는 것이 서툴다. 동료와 달리기 경주를 하는 사이에 하반신이 튼튼하게 성장한다.', 'It can’t run properly when it’s newly born. As it races around with others of its kind, its legs grow stronger.'),
  ('galar', 334, 78, false, '불타는 갈기를 휘날리며 시속 240km의 속도로 넓은 초원을 달려나간다.', 'This Pokémon can be seen galloping through fields at speeds of up to 150 mph, its fiery mane fluttering in the wind.'),
  ('galar', 334, 10322, true, '불타는 갈기를 휘날리며 시속 240km의 속도로 넓은 초원을 달려나간다.', 'This Pokémon can be seen galloping through fields at speeds of up to 150 mph, its fiery mane fluttering in the wind.'),
  ('galar', 365, 122, false, '커다란 손바닥은 팬터마임을 하기 위해 발달했다고 생각하는 학자도 많다.', 'The broadness of its hands may be no coincidence—many scientists believe its palms became enlarged specifically for pantomiming.'),
  ('galar', 365, 10327, true, '커다란 손바닥은 팬터마임을 하기 위해 발달했다고 생각하는 학자도 많다.', 'The broadness of its hands may be no coincidence—many scientists believe its palms became enlarged specifically for pantomiming.'),
  ('galar', 367, 554, false, '몸 안에서 타오르는 불꽃이 힘의 원천이다. 불꽃이 작아지면 금세 잠들어 버린다.', 'It derives its power from fire burning inside its body. If the fire dwindles, this Pokémon will immediately fall asleep.'),
  ('galar', 367, 10335, true, '몸 안에서 타오르는 불꽃이 힘의 원천이다. 불꽃이 작아지면 금세 잠들어 버린다.', 'It derives its power from fire burning inside its body. If the fire dwindles, this Pokémon will immediately fall asleep.'),
  ('galar', 368, 555, false, '혈기왕성한 포켓몬. 굵직한 팔에서 날리는 펀치는 덤프트럭도 가루로 만들어버린다.', 'The thick arms of this hot-blooded Pokémon can deliver punches capable of obliterating a dump truck.'),
  ('galar', 368, 10336, true, '혈기왕성한 포켓몬. 굵직한 팔에서 날리는 펀치는 덤프트럭도 가루로 만들어버린다.', 'The thick arms of this hot-blooded Pokémon can deliver punches capable of obliterating a dump truck.'),
  ('galar', 401, 79, false, '멍청하고 둔감하다. 꼬리를 먹혀도 아픔을 느끼지 못하고 꼬리가 다시 자라도 눈치채지 못한다.', 'Slow-witted and oblivious, this Pokémon won’t feel any pain if its tail gets eaten. It won’t notice when its tail grows back, either.'),
  ('galar', 401, 10323, true, '멍청하고 둔감하다. 꼬리를 먹혀도 아픔을 느끼지 못하고 꼬리가 다시 자라도 눈치채지 못한다.', 'Slow-witted and oblivious, this Pokémon won’t feel any pain if its tail gets eaten. It won’t notice when its tail grows back, either.'),
  ('galar', 402, 80, false, '셀러에게 꼬리를 물려서 진화했다. 셀러는 꼬리에서 배어 나오는 단맛에 황홀한 기분이다.', 'Slowpoke became Slowbro when a Shellder bit on to its tail. Sweet flavors seeping from the tail make the Shellder feel as if its life is a dream.'),
  ('galar', 402, 10324, true, '셀러에게 꼬리를 물려서 진화했다. 셀러는 꼬리에서 배어 나오는 단맛에 황홀한 기분이다.', 'Slowpoke became Slowbro when a Shellder bit on to its tail. Sweet flavors seeping from the tail make the Shellder feel as if its life is a dream.'),
  ('galar', 403, 199, false, '셀러의 독소가 야돈의 뇌를 돌아다니면서 숨겨진 지능을 기적적으로 각성시켰다.', 'Miraculously, this former Slowpoke’s latent intelligence was drawn out when Shellder poison raced through its brain.'),
  ('galar', 403, 10331, true, '셀러의 독소가 야돈의 뇌를 돌아다니면서 숨겨진 지능을 기적적으로 각성시켰다.', 'Miraculously, this former Slowpoke’s latent intelligence was drawn out when Shellder poison raced through its brain.'),
  ('galar', 576, 144, false, '푸르고 아름다운 날개는 얼음으로 되어 있다고 전해진다. 긴 꼬리를 나부끼며 설산 위를 난다.', 'It’s said that this Pokémon’s beautiful blue wings are made of ice. Articuno flies over snowy mountains, its long tail fluttering along behind it.'),
  ('galar', 576, 10328, true, '푸르고 아름다운 날개는 얼음으로 되어 있다고 전해진다. 긴 꼬리를 나부끼며 설산 위를 난다.', 'It’s said that this Pokémon’s beautiful blue wings are made of ice. Articuno flies over snowy mountains, its long tail fluttering along behind it.'),
  ('galar', 577, 145, false, '전기를 자유로이 조종한다. 새까만 번개 구름 안에 거처가 있다고 전해지고 있다.', 'This Pokémon has complete control over electricity. There are tales of Zapdos nesting in the dark depths of pitch-black thunderclouds.'),
  ('galar', 577, 10329, true, '전기를 자유로이 조종한다. 새까만 번개 구름 안에 거처가 있다고 전해지고 있다.', 'This Pokémon has complete control over electricity. There are tales of Zapdos nesting in the dark depths of pitch-black thunderclouds.'),
  ('galar', 578, 146, false, '날갯짓을 하면 날개의 불꽃이 빨갛고 아름답게 빛나는 전설의 새포켓몬 중 1마리다.', 'It’s one of the legendary bird Pokémon. When Moltres flaps its flaming wings, they glimmer with a dazzling red glow.'),
  ('galar', 578, 10330, true, '날갯짓을 하면 날개의 불꽃이 빨갛고 아름답게 빛나는 전설의 새포켓몬 중 1마리다.', 'It’s one of the legendary bird Pokémon. When Moltres flaps its flaming wings, they glimmer with a dazzling red glow.'),
  ('hisui', 3, 724, false, '0.1초 만에 화살깃을 날개에 달린 시위에 메겨 발사한다. 상대가 알아차리기 전에 급소를 꿰뚫어버린다.', 'The air stored inside the rachises of Decidueye''s feathers insulates the Pokémon against Hisui''s extreme cold. This is firm proof that evolution can be influenced by environment.'),
  ('hisui', 3, 10413, true, '0.1초 만에 화살깃을 날개에 달린 시위에 메겨 발사한다. 상대가 알아차리기 전에 급소를 꿰뚫어버린다.', 'The air stored inside the rachises of Decidueye''s feathers insulates the Pokémon against Hisui''s extreme cold. This is firm proof that evolution can be influenced by environment.'),
  ('hisui', 6, 157, false, '작열하는 불꽃으로 주변에 아지랑이를 만들어내서 모습을 숨길 수 있다. 불타오르며 폭발하는 바람은 모든 것을 태운다.', 'Said to purify lost, forsaken souls with its flames and guide them to the afterlife. I believe its form has been influenced by the energy of the sacred mountain towering at Hisui''s center.'),
  ('hisui', 6, 10402, true, '작열하는 불꽃으로 주변에 아지랑이를 만들어내서 모습을 숨길 수 있다. 불타오르며 폭발하는 바람은 모든 것을 태운다.', 'Said to purify lost, forsaken souls with its flames and guide them to the afterlife. I believe its form has been influenced by the energy of the sacred mountain towering at Hisui''s center.'),
  ('hisui', 9, 503, false, '갑옷에 내장된 검으로 한칼에 상대를 제압한다. 눈빛만으로 상대를 침묵시킨다.', 'Hard of heart and deft of blade, this rare form of Samurott is a product of the Pokémon''s evolution in the region of Hisui. Its turbulent blows crash into foes like ceaseless pounding waves.'),
  ('hisui', 9, 10405, true, '갑옷에 내장된 검으로 한칼에 상대를 제압한다. 눈빛만으로 상대를 침묵시킨다.', 'Hard of heart and deft of blade, this rare form of Samurott is a product of the Pokémon''s evolution in the region of Hisui. Its turbulent blows crash into foes like ceaseless pounding waves.'),
  ('hisui', 84, 211, false, '전신의 작은 바늘은 비늘이 변화한 것이다. 찔리면 독 때문에 정신을 잃게 된다.', 'Fishers detest this troublesome Pokémon because it sprays poison from its spines, getting it everywhere. A different form of Qwilfish lives in other regions.'),
  ('hisui', 84, 10403, true, '전신의 작은 바늘은 비늘이 변화한 것이다. 찔리면 독 때문에 정신을 잃게 된다.', 'Fishers detest this troublesome Pokémon because it sprays poison from its spines, getting it everywhere. A different form of Qwilfish lives in other regions.'),
  ('hisui', 94, 549, false, '꽃으로 만든 정유는 최고의 향을 내지만 눈이 튀어나올 정도로 비싸다.', 'I suspect that its well-developed legs are the result of a life spent on mountains covered in deep snow. The scent it exudes from its flower crown heartens those in proximity.'),
  ('hisui', 94, 10406, true, '꽃으로 만든 정유는 최고의 향을 내지만 눈이 튀어나올 정도로 비싸다.', 'I suspect that its well-developed legs are the result of a life spent on mountains covered in deep snow. The scent it exudes from its flower crown heartens those in proximity.'),
  ('hisui', 116, 705, false, '등의 돌기 안에 작은 뇌가 있다. 먹이에 대한 생각과 적으로부터 도망치는 생각만 한다.', 'A creature given to melancholy. I suspect its metallic shell developed as a result of the mucus on its skin reacting with the iron in Hisui''s water.'),
  ('hisui', 116, 10410, true, '등의 돌기 안에 작은 뇌가 있다. 먹이에 대한 생각과 적으로부터 도망치는 생각만 한다.', 'A creature given to melancholy. I suspect its metallic shell developed as a result of the mucus on its skin reacting with the iron in Hisui''s water.'),
  ('hisui', 117, 706, false, '긴 뿔을 기세 좋게 늘여서 공격한다. 위력은 헤비급 복서 펀치의 100배다.', 'Able to freely control the hardness of its metallic shell. It loathes solitude and is extremely clingy—it will fume and run riot if those dearest to it ever leave its side.'),
  ('hisui', 117, 10411, true, '긴 뿔을 기세 좋게 늘여서 공격한다. 위력은 헤비급 복서 펀치의 100배다.', 'Able to freely control the hardness of its metallic shell. It loathes solitude and is extremely clingy—it will fume and run riot if those dearest to it ever leave its side.'),
  ('hisui', 150, 58, false, '충직한 성격으로 자신의 트레이너를 지키기 위해 필사적으로 상대방에게 짖어댄다.', 'They patrol their territory in pairs. I believe the igneous rock components in the fur of this species are the result of volcanic activity in its habitat.'),
  ('hisui', 150, 10398, true, '충직한 성격으로 자신의 트레이너를 지키기 위해 필사적으로 상대방에게 짖어댄다.', 'They patrol their territory in pairs. I believe the igneous rock components in the fur of this species are the result of volcanic activity in its habitat.'),
  ('hisui', 151, 59, false, '옛날부터 많은 사람의 마음을 사로잡은 아름다운 포켓몬이다. 마치 나는 것처럼 경쾌하게 달린다.', 'Snaps at its foes with fangs cloaked in blazing flame. Despite its bulk, it deftly feints every which way, leading opponents on a deceptively merry chase as it all but dances around them.'),
  ('hisui', 151, 10399, true, '옛날부터 많은 사람의 마음을 사로잡은 아름다운 포켓몬이다. 마치 나는 것처럼 경쾌하게 달린다.', 'Snaps at its foes with fangs cloaked in blazing flame. Despite its bulk, it deftly feints every which way, leading opponents on a deceptively merry chase as it all but dances around them.'),
  ('hisui', 192, 100, false, '몬스터볼과 닮은 것은 보호색으로 위장하기 위해서라고 전해지나 의외로 쉽게 자폭한다.', 'An enigmatic Pokémon that happens to bear a resemblance to a Poké Ball. When excited, it discharges the electric current it has stored in its belly, then lets out a great, uproarious laugh.'),
  ('hisui', 192, 10400, true, '몬스터볼과 닮은 것은 보호색으로 위장하기 위해서라고 전해지나 의외로 쉽게 자폭한다.', 'An enigmatic Pokémon that happens to bear a resemblance to a Poké Ball. When excited, it discharges the electric current it has stored in its belly, then lets out a great, uproarious laugh.'),
  ('hisui', 193, 101, false, '조금이라도 충격을 주면 체내에 있는 전기 에너지가 넘쳐서 폭발해버린다.', 'The tissue on the surface of its body is curiously similar in composition to an Apricorn. When irritated, this Pokémon lets loose an electric current equal to 20 lightning bolts.'),
  ('hisui', 193, 10401, true, '조금이라도 충격을 주면 체내에 있는 전기 에너지가 넘쳐서 폭발해버린다.', 'The tissue on the surface of its body is curiously similar in composition to an Apricorn. When irritated, this Pokémon lets loose an electric current equal to 20 lightning bolts.'),
  ('hisui', 202, 215, false, '교활하고 사나운 성질을 가졌다. 부모가 없는 틈에 둥지로 침입해서 알을 훔친다.', 'Its sturdy, curved claws are ideal for traversing precipitous cliffs. From the tips of these claws drips a venom that infiltrates the nerves of any prey caught in Sneasel''s grasp.'),
  ('hisui', 202, 10404, true, '교활하고 사나운 성질을 가졌다. 부모가 없는 틈에 둥지로 침입해서 알을 훔친다.', 'Its sturdy, curved claws are ideal for traversing precipitous cliffs. From the tips of these claws drips a venom that infiltrates the nerves of any prey caught in Sneasel''s grasp.'),
  ('hisui', 216, 713, false, '낮 동안의 활동으로 몸의 균열이 깊어지지만 하룻밤 사이에 균열이 없는 몸으로 돌아간다.', 'The armor of ice covering its lower jaw puts steel to shame and can shatter rocks with ease. This Pokémon barrels along steep mountain paths, cleaving through the deep snow.'),
  ('hisui', 216, 10412, true, '낮 동안의 활동으로 몸의 균열이 깊어지지만 하룻밤 사이에 균열이 없는 몸으로 돌아간다.', 'The armor of ice covering its lower jaw puts steel to shame and can shatter rocks with ease. This Pokémon barrels along steep mountain paths, cleaving through the deep snow.'),
  ('hisui', 219, 570, false, '먹이를 찾아 사람으로 둔갑하여 마을에 나타나기도 한다. 주로 아이로 둔갑한다.', 'A once-departed soul, returned to life in Hisui. Derives power from resentment, which rises as energy atop its head and takes on the forms of foes. In this way, Zorua vents lingering malice.'),
  ('hisui', 219, 10407, true, '먹이를 찾아 사람으로 둔갑하여 마을에 나타나기도 한다. 주로 아이로 둔갑한다.', 'A once-departed soul, returned to life in Hisui. Derives power from resentment, which rises as energy atop its head and takes on the forms of foes. In this way, Zorua vents lingering malice.'),
  ('hisui', 220, 571, false, '고독한 트레이너는 조로아크에게 환상을 보여주도록 명령하여 혼자만의 외로움을 달랜다.', 'With its disheveled white fur, it looks like an embodiment of death. Heedless of its own safety, Zoroark attacks its nemeses with a bitter energy so intense, it lacerates Zoroark''s own body.'),
  ('hisui', 220, 10408, true, '고독한 트레이너는 조로아크에게 환상을 보여주도록 명령하여 혼자만의 외로움을 달랜다.', 'With its disheveled white fur, it looks like an embodiment of death. Heedless of its own safety, Zoroark attacks its nemeses with a bitter energy so intense, it lacerates Zoroark''s own body.'),
  ('hisui', 222, 628, false, '혈기왕성하고 거칠어서 가라르의 배달부 자리는 아머까오에게 뺏겼다.', 'Screaming a bloodcurdling battle cry, this huge and ferocious bird Pokémon goes out on the hunt. It blasts lakes with shock waves, then scoops up any prey that float to the water''s surface.'),
  ('hisui', 222, 10409, true, '혈기왕성하고 거칠어서 가라르의 배달부 자리는 아머까오에게 뺏겼다.', 'Screaming a bloodcurdling battle cry, this huge and ferocious bird Pokémon goes out on the hunt. It blasts lakes with shock waves, then scoops up any prey that float to the water''s surface.'),
  ('paldea', 53, 194, false, '지상에서 걸을 때는 피부가 건조해지지 않도록 독성분의 점막으로 몸을 감싸고 있다.', 'When walking on land, it covers its body with a poisonous film that keeps its skin from dehydrating.'),
  ('paldea', 53, 10422, true, '지상에서 걸을 때는 피부가 건조해지지 않도록 독성분의 점막으로 몸을 감싸고 있다.', 'When walking on land, it covers its body with a poisonous film that keeps its skin from dehydrating.'),
  ('paldea', 223, 128, false, '가라르에 서식하는 켄타로스는 기질이 거칠어서 사람이 등에 올라타는 것을 허용하지 않는다.', 'The Tauros of the Galar region are volatile in nature, and they won’t allow people to ride on their backs.'),
  ('paldea', 223, 10419, true, '가라르에 서식하는 켄타로스는 기질이 거칠어서 사람이 등에 올라타는 것을 허용하지 않는다.', 'The Tauros of the Galar region are volatile in nature, and they won’t allow people to ride on their backs.')
